  <script>
    // Normalise typed Arabic-Indic (٠-٩) or Persian (۰-۹) digits to Western digits
    function toWesternDigits(str) {
      return str
        .replace(/[٠-٩]/g, d => d.charCodeAt(0) - 1632)
        .replace(/[۰-۹]/g, d => d.charCodeAt(0) - 1776);
    }

    const modal = document.getElementById('editModal');
    const modalTitle = document.getElementById('modalTitle');
    const inputLabel = document.getElementById('inputLabel');
    const modalInput = document.getElementById('modalInput');
    const editTargetKey = document.getElementById('editTargetKey');

    function openEditModal(targetKey, labelText, currentValue, inputType) {
      editTargetKey.value = targetKey;
      modalTitle.textContent = 'تعديل ' + labelText;
      inputLabel.textContent = labelText;

      modalInput.type = inputType || 'text';
      modalInput.value = currentValue;

      if (targetKey === 'phone') {
        modalInput.setAttribute('inputmode', 'tel');
      } else if (targetKey === 'iban') {
        modalInput.setAttribute('inputmode', 'text');
        modalInput.setAttribute('maxlength', '32');
      } else {
        modalInput.removeAttribute('inputmode');
      }

      modal.classList.add('is-open');
      modalInput.focus();
    }

    function closeEditModal() {
      modal.classList.remove('is-open');
    }

    // Close when clicking the backdrop
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        closeEditModal();
      }
    });

    // Close on Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('is-open')) {
        closeEditModal();
      }
    });

    function handleFormSubmit(e) {
      e.preventDefault();
      const target = editTargetKey.value;
      const rawValue = modalInput.value.trim();
      const normalizedValue = toWesternDigits(rawValue);

      if (target === 'name-email') {
        const emailEl = document.getElementById('display-email');
        if (emailEl) emailEl.textContent = normalizedValue;
      } else if (target === 'phone') {
        const phoneEl = document.getElementById('display-phone');
        if (phoneEl) phoneEl.textContent = normalizedValue;
      } else if (target === 'iban') {
        const ibanEl = document.getElementById('display-iban');
        if (ibanEl) ibanEl.textContent = normalizedValue.toUpperCase();
      }

      closeEditModal();
    }
  </script>
